import { useState, type FormEvent, type ReactElement } from "react";
import { Alert, Button, Stack, TextField } from "@mui/material";
import { parseQuantity } from "./quantity";

export interface QuantityFormProps {
  requestQuote: (quantity: number) => Promise<string>;
}

export function QuantityForm({ requestQuote }: QuantityFormProps): ReactElement {
  const [value, setValue] = useState("");
  const [attempted, setAttempted] = useState(false);
  const [pending, setPending] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const quantity = parseQuantity(value);
  async function submit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    setAttempted(true);
    if (quantity === null || pending) return;
    setPending(true);
    setResult(null);
    setFailed(false);
    try {
      setResult(await requestQuote(quantity));
    } catch {
      setFailed(true);
    } finally {
      setPending(false);
    }
  }
  return (
    <Stack component="form" onSubmit={submit} spacing={2}>
      <TextField label="Quantity" value={value} disabled={pending}
        onChange={(event) => setValue(event.target.value)}
        error={attempted && quantity === null}
        helperText={attempted && quantity === null ? "Enter a whole quantity from 1 to 1000" : undefined} />
      <Button type="submit" disabled={pending}>{pending ? "Requesting quote" : "Get quote"}</Button>
      {result !== null && <output aria-label="Quoted price">{result}</output>}
      {failed && <Alert severity="error">Quote unavailable. Try again.</Alert>}
    </Stack>
  );
}

